using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.UI;
namespace LostRealmsOW {public static class BoardForgeValidation {
 static OpenWorldManager GM=>UnityEngine.Object.FindObjectsByType<OpenWorldManager>().First(g=>g.Hero);
 static OpenWorldNPC Brom=>UnityEngine.Object.FindObjectsByType<OpenWorldNPC>().First(n=>n.NpcId=="brom");
 public static void Report(){var lines=new System.Collections.Generic.List<string>();void Check(bool ok,string label){lines.Add((ok?"PASS ":"FAIL ")+label);}
  var smith=Brom;Check(smith.Visual.ModelInstance.name=="Brom_AccuRig","AccuRig replaces Brom");var driver=smith.Visual.ModelInstance.GetComponent<OpenWorldImportedModel>();Check(driver&&driver.Idle&&driver.Walk&&driver.Talk,"native idle walk talk present");
  var mats=smith.Visual.ModelInstance.GetComponentsInChildren<SkinnedMeshRenderer>().SelectMany(r=>r.sharedMaterials);Check(mats.All(m=>m&&m.mainTexture),"all smith slots textured");
  float min=999,max=-999;foreach(var r in smith.Visual.ModelInstance.GetComponentsInChildren<SkinnedMeshRenderer>()){var mesh=new Mesh();r.BakeMesh(mesh,false);foreach(var v in mesh.vertices){float y=r.transform.TransformPoint(v).y;min=Mathf.Min(min,y);max=Mathf.Max(max,y);}UnityEngine.Object.DestroyImmediate(mesh);}
  float terrain=GM.ActiveTerrain.SampleHeight(smith.transform.position)+GM.ActiveTerrain.transform.position.y;Check(min>terrain-.12f&&min<terrain+.35f,"smith grounded min="+min.ToString("F2")+" terrain="+terrain.ToString("F2"));Check(max-min>1.65f&&max-min<2.15f,"smith height="+(max-min).ToString("F2"));
  var workshop=GameObject.Find("Blacksmith_RoyalForge_Workshop");var building=workshop.transform.Cast<Transform>().First(t=>t.name.Contains("Blacksmith_Building"));Check(Vector3.Dot(building.forward,Vector3.left)>.99f,"tool side rotated toward midtown");var bounds=OpenWorldMaterialHelper.ComputeRendererBounds(building);Check(smith.transform.position.x>bounds.max.x+.2f,"smith outside workshop tool side");lines.Add("workshop "+bounds+" smith "+smith.transform.position);
  foreach(var board in UnityEngine.Object.FindObjectsByType<OpenWorldNoticeBoard>()){Check(board.transform.position.x< -5&&board.transform.position.z>26,"board placed beside northern road");Check(board.transform.Find("Pinned parchment")&&board.transform.Find("Printed parchment ink"),"physical paper with fixed ink");Check(board.transform.Find("Pitched rain cap"),"timber roof present");foreach(var ink in board.GetComponentsInChildren<Text>())Check(ink.preferredHeight<=ink.rectTransform.rect.height+1,"parchment text fits: "+ink.name);float clearance=999;foreach(var road in OpenWorldRegions.Roads)clearance=Mathf.Min(clearance,OpenWorldRegions.DistanceToPath(road.Path,new Vector2(board.transform.position.x,board.transform.position.z),out _,out _)-road.Width*.5f);Check(clearance>1.3f,"board footprint clear of road edge "+clearance.ToString("F1"));}
  File.WriteAllLines("Docs/QA/BOARD_FORGE.txt",lines);Debug.Log(string.Join("\n",lines));
 }
 public static void OpenModal(){var gm=GM;gm.CloseMenus();gm.ShowQuestBoardModal=true;typeof(OpenWorldMobileHud).GetMethod("TickQuestBoard",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(OpenWorldMobileHud.Instance,new object[]{gm});}
 public static void CheckModal(){var lines=new System.Collections.Generic.List<string>();var root=GameObject.Find("Quest Board");var scroll=root.GetComponentInChildren<ScrollRect>();lines.Add((scroll&&scroll.content.childCount==5?"PASS ":"FAIL ")+"five quest rows in clipped scroll list");foreach(var label in scroll.content.GetComponentsInChildren<Text>()){var row=label.rectTransform.parent as RectTransform;var corners=new Vector3[4];label.rectTransform.GetWorldCorners(corners);bool inside=corners.All(c=>{var p=row.InverseTransformPoint(c);return row.rect.Contains(new Vector2(p.x,p.y));});lines.Add((inside?"PASS ":"FAIL ")+"text contained: "+label.text);}
 File.WriteAllLines("Docs/QA/QUEST_BOARD_MODAL.txt",lines);Debug.Log(string.Join("\n",lines));}
 public static void CloseModal(){GM.CloseMenus();}
 public static void Talk(){Brom.Visual.Play("talk",true);Brom.enabled=false;Brom.GetComponent<OpenWorldNpcRoutine>().enabled=false;}
 public static void Idle(){Brom.Visual.Play("idle",true);}
 public static void FocusBoards(){Focus(new Vector3(-7.3f,6.2f,29),new Vector3(0,2.6f,-5.2f),1.6f);}
 public static void FocusForge(){Focus(new Vector3(-16,6.2f,9.2f),new Vector3(10,3.5f,-4),1.6f);}
 public static void FocusSmith(){Focus(Brom.transform.position,new Vector3(3,2.1f,-2.5f),1.1f);}
 static void Focus(Vector3 p,Vector3 offset,float h){GM.CameraRig.enabled=false;Camera.main.transform.position=p+offset;Camera.main.transform.LookAt(p+Vector3.up*h);}

 static Vector3 beforeMine;static int beforeOre;static GatherNode target;
 public static void PrepareMining(){var gm=GM;beforeMine=gm.Hero.transform.position;beforeOre=gm.Ore;target=UnityEngine.Object.FindObjectsByType<GatherNode>().First(n=>n.name.Contains("ore"));gm.CloseMenus();gm.Hero.WarpTo(target.transform.position+Vector3.back*1.4f);Focus(target.transform.position,new Vector3(3,2,-3),.4f);}
 public static void CheckMining(){var gm=GM;var lines=new System.Collections.Generic.List<string>();void Check(bool ok,string label){lines.Add((ok?"PASS ":"FAIL ")+label);}
 try{Check(gm.Ore==beforeOre,"standing over ore does not auto collect");var hud=OpenWorldMobileHud.Instance;var update=typeof(OpenWorldMobileHud).GetMethod("UpdateMiningControl",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);update.Invoke(hud,null);var button=(UnityEngine.UI.Button)typeof(OpenWorldMobileHud).GetField("mineControl",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(hud);Check(button&&button.gameObject.activeSelf,"contextual Mine button visible");Check(target.TryMine(gm),"explicit mine succeeds");Check(gm.Ore==beforeOre+1,"one ore awarded");Check(!target.TryMine(gm)&&gm.Ore==beforeOre+1,"duplicate mine refused");update.Invoke(hud,null);Check(!button.gameObject.activeSelf,"Mine button hides after mining");var visual=target.GetComponentInChildren<OpenWorldOreVisual>(true);Check(Mathf.Abs(visual.transform.localPosition.y+.425f)<.001f,"ore visual buried half host height");}
 finally{gm.Ore=beforeOre;gm.Hero.WarpTo(beforeMine);File.WriteAllLines("Docs/QA/ORE_MINING.txt",lines);Debug.Log(string.Join("\n",lines));}}
}}
